// Typed bindings for a Sley program, generated by sley_agent::embed::bindgen::typescript.
// Do not edit: regenerate them when the program's interface changes.
//
// Values travel in the JSON form of Module::call_json. Integers are JSON
// numbers, which JavaScript holds exactly up to 2^53 - 1.

/** `variant Kind { None, None_ }` */
export type Kind = "None" | "None_";

/** `record Program { x: i64 }` */
export interface Program_ {
  x: number;
}

/** `record Program_ { y: i64 }` */
export interface Program__ {
  y: number;
}

/** How a call ended: its value, a trap's name, or the limit it reached. */
export type CallResult<T> = { value: T } | { trap: string } | { limit: string };

/** One call's result and exact resource use. */
export interface CallOutcome<T> {
  result: CallResult<T>;
  fuel_used: number;
  instructions: number;
}

/** The host's export of Module::call_json: a function's name, its arguments
 * as a JSON array and a fuel limit, to the JSON reply. */
export type CallJson = (name: string, args: string, fuelLimit: number) => string;

/** The signatures these bindings were generated from. */
export const SIGNATURES: readonly string[] = [
  "callJson(reply: i64, JSON: i64) -> Program_",
  "module(args: i64) -> i64",
  "new(args: i64, fuel_limit: i64, fuel_limit_: i64) -> i64",
  "new_(x: Program, k: Kind) -> i64",
];

/** The program's functions with TypeScript types, over the host's call_json. */
export class Program {
  readonly #call: CallJson;

  constructor(call: CallJson) {
    this.#call = call;
  }

  /** `callJson(reply: i64, JSON: i64) -> Program_` */
  callJson(reply_: number, JSON_: number, fuelLimit: number): CallOutcome<Program__> {
    const reply = this.#call("callJson", JSON.stringify([reply_, JSON_]), fuelLimit);
    return JSON.parse(reply) as CallOutcome<Program__>;
  }

  /** `module(args: i64) -> i64` */
  module(args: number, fuelLimit: number): CallOutcome<number> {
    const reply = this.#call("module", JSON.stringify([args]), fuelLimit);
    return JSON.parse(reply) as CallOutcome<number>;
  }

  /** `new(args: i64, fuel_limit: i64, fuel_limit_: i64) -> i64` */
  new_(args: number, fuel_limit: number, fuel_limit_: number, fuelLimit: number): CallOutcome<number> {
    const reply = this.#call("new", JSON.stringify([args, fuel_limit, fuel_limit_]), fuelLimit);
    return JSON.parse(reply) as CallOutcome<number>;
  }

  /** `new_(x: Program, k: Kind) -> i64` */
  new__(x: Program_, k: Kind, fuelLimit: number): CallOutcome<number> {
    const reply = this.#call("new_", JSON.stringify([x, k]), fuelLimit);
    return JSON.parse(reply) as CallOutcome<number>;
  }
}
